func productExceptSelf(_ nums: [Int]) -> [Int] {
    var out = [Int](repeating: 1, count: nums.count)
    var prefix = 1
    for i in nums.indices { out[i] = prefix; prefix *= nums[i] }
    var suffix = 1
    for i in nums.indices.reversed() { out[i] *= suffix; suffix *= nums[i] }
    return out
}
